steps.action:
curl -s https://api.linear.app/graphql \
  -X POST \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "
    {
      issues(filter: {
        assignee: { name: { eq: \"Maya Chen\" } },
        project: { name: { eq: \"Atlas\" } },
        team: { name: { eq: \"Web\" } },
        milestone: { name: { eq: \"Cycle 4\" } }
      }) {
        nodes {
          id
          identifier
          title
          priority
        }
      }
    }"
  }'
